llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Emtricitabine, a polar cytidine nucleoside analogue, achieved 93% absolute oral bioavailability in humans, showing that nucleoside polarity does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Doxifluridine, a deoxynucleoside analogue, showed 80% oral bioavailability in patients, supporting high F for nucleoside-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Dapagliflozin, a C-glucoside with a sugar moiety, had 78% absolute oral bioavailability in healthy subjects, supporting high F for glycoside-containing polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Tofogliflozin, another C-glucoside, showed 97.5% absolute oral bioavailability in humans, further supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Acyclovir, a guanine-derived nucleoside analogue, had oral bioavailability of 0.2 (20%), meeting the F>=20% threshold and weakly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Didanosine, a dideoxynucleoside, had F=0.19 in fed patients, below the 20% threshold, providing condition-dependent contradictory evidence; fasting F was 0.22-0.28 and solution F was 38%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the physicochemical prior is low, the preponderance of highly transferable experimental evidence from nucleoside and glycoside analogues shows oral bioavailability at or above 20%, often 78-97.5%; the only sub-20% value is condition-dependent fed didanosine. Therefore predict high F.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for guanosine itself.",
    "Acid stability and intestinal transporter involvement for guanosine are not directly evidenced.",
    "Fed-state didanosine low F raises uncertainty about condition-dependent absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

